import sys

MOD = 998244353

def extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, y, x = extended_gcd(b % a, a)
        return (g, x - (b // a) * y, y)

def inverse(a, mod):
    g, x, y = extended_gcd(a, mod)
    if g != 1:
        return 0
    else:
        return (x % mod)

def mod(a, m):
    return ((a % m) + m) % m

def calculate(N, M, K):
    invM = inverse(M, MOD)
    expect = [0] * (K + 1)
    expect[0] = 1
    poly = [0] * (K + 1)
    poly[0] = 1
    currentExpect = 1
    for k in range(1, K + 1):
        numerator = 1
        for i in range(k):
            numerator *= (N - i)
            numerator %= MOD
        currentExpect = numerator * invM % MOD
        for i in range(k, -1, -1):
            prevPoly = poly[i - 1] if i > 0 else 0
            poly[i] = prevPoly - (k - 1) * poly[i]
            poly[i] = mod(poly[i], MOD)
        expect[k] = currentExpect
        for i in range(k - 1, -1, -1):
            expect[k] -= poly[i] * expect[i]
            expect[k] = mod(expect[k], MOD)
    return expect[K]

def main():
    line = sys.stdin.readline().strip()
    parts = line.split()
    N, M, K = map(int, parts)
    result = calculate(N, M, K)
    print(result)

if __name__ == "__main__":
    main()

